const sk = (how, sig, extra = '') => `rm -f /tmp/m36.*; exec 2>/dev/null; set -m; node sk.js ${how} ${sig} ${extra}; echo "rc=$?"; for f in /tmp/m36.*; do [ -e "$f" ] && echo "ran: \${f#/tmp/m36.}"; done; true`;
const cases = [];
for (const how of ['pid', 'zero', 'pgid']) cases.push({ name: `term-${how}`, cmd: sk(how, 'SIGTERM') });
for (const sig of ['SIGINT', 'SIGHUP', 'SIGQUIT', 'SIGKILL', 'SIGABRT', 'SIGUSR2', 'SIGALRM', 'SIGPIPE', 'SIGSEGV', 'SIGXCPU', 'SIGVTALRM', 15, 9]) cases.push({ name: `pid-${sig}`, cmd: sk('pid', sig) });
cases.push({ name: 'abort', cmd: sk('abort', '-') });
cases.push({ name: 'flush-file', cmd: 'rm -f /tmp/m36.*; BIG=1000000 node sk.js pid SIGTERM > /tmp/m36o; echo "rc=$?"; wc -c < /tmp/m36o | tr -d " "; head -c 22 /tmp/m36o; echo' });
cases.push({ name: 'flush-pipe', cmd: 'rm -f /tmp/m36.*; BIG=20000 node sk.js pid SIGTERM | wc -c | tr -d " "; echo "rc=${PIPESTATUS[0]}"' });
cases.push({ name: 'parent-sees', cmd: 'node -e "const r = require(\'child_process\').spawnSync(process.execPath, [\'sk.js\', \'pid\', process.argv[1]]); console.log(r.status, r.signal, JSON.stringify(String(r.stdout)))" SIGHUP; node -e "const r = require(\'child_process\').spawnSync(process.execPath, [\'sk.js\', \'abort\']); console.log(r.status, r.signal)"' });
cases.push({ name: 'parent-async', cmd: 'node -e "require(\'child_process\').spawn(process.execPath, [\'sk.js\', \'pid\', \'SIGINT\']).on(\'exit\', (c, s) => console.log(\'exit\', c, s))"' });
cases.push({ name: 'bash-sees', cmd: 'exec 2>/dev/null; node sk.js pid SIGTERM > /dev/null; s=$?; echo "status $s $(kill -l $((s - 128)) 2>/dev/null)"' });
cases.push({ name: 'handled', cmd: 'node handled.js SIGTERM SIGINT SIGHUP SIGUSR2; echo "rc=$?"' });
cases.push({ name: 'handled-then-removed', cmd: 'node -e "const h = () => console.log(\'h\'); process.on(\'SIGTERM\', h); process.kill(process.pid, \'SIGTERM\'); setTimeout(() => { process.off(\'SIGTERM\', h); try { process.kill(process.pid, \'SIGTERM\') } finally { console.log(\'finally\') } }, 20)"; echo "rc=$?"' });
cases.push({ name: 'ignored', cmd: 'node ignored.js SIGWINCH SIGCHLD SIGURG SIGCONT 0; echo "rc=$?"' });
cases.push({ name: 'usr1', cmd: 'node --inspect-port=0 -e "console.log(\'kill USR1\', process.kill(process.pid, \'SIGUSR1\')); setTimeout(() => console.log(\'alive\'), 30)" 2>/dev/null; echo "rc=$?"' });
cases.push({ name: 'other', cmd: 'node other.js; echo "rc=$?"', timeout: 30000 });
cases.push({ name: 'kill-bash-parent', cmd: 'bash -c \'node -e "process.kill(process.ppid, \\"SIGTERM\\"); setTimeout(() => console.log(\\"child alive\\"), 50)"; echo "inner after"\'; echo "outer rc=$?"' });
export default cases;
